def env_float(name: str, default: float) -> float:
    raw = os.environ.get(name, "").strip()
    try:
        return float(raw) if raw else default
    except ValueError:
        return default


def env_int(name: str, default: int) -> int:
    return int(env_float(name, float(default)))


def kill_sell_file() -> Path:
    p = os.environ.get("BLOOM_KILL_SELL_FILE", "").strip()
    return Path(p) if p else Path("/etc/bloom-executor/KILL_SELL")


def secrets_for_scrub() -> list:
    return [v for v in (os.environ.get("BLOOM_API_KEY", ""),
                         os.environ.get("HELIUS_API_KEY", ""),
                         os.environ.get("HELIUS_API", "")) if v]


def scrub_all(text: str) -> str:
    for k in secrets_for_scrub():
        text = scrub(text, k)
    return text


_МЕТР = None
_МЕТР_ПРОБОВАЛИ = False
_УЧЁТ_ПИШЕТСЯ = None
_УЧЁТ_ПОЧЕМУ = ""


def метр_кредитов():
    """Счётчик кредитов сторожа. Один на процесс, создаётся лениво.

    Модель кредитов берётся из solana_rpc_client -- та, что уже
    согласована. Пишется в каталог состояния: на хосте дерево репозитория
    службе недоступно (ProtectHome=read-only).
    """
    global _МЕТР, _МЕТР_ПРОБОВАЛИ  # noqa: PLW0603
    if _МЕТР_ПРОБОВАЛИ:
        return _МЕТР
    _МЕТР_ПРОБОВАЛИ = True
    try:
        from bloom_exec_state import state_dir  # noqa: PLC0415
        from solana_rpc_client import CreditMeter  # noqa: PLC0415
        каталог = state_dir() / "helius_usage"
        каталог.mkdir(parents=True, exist_ok=True)
        _МЕТР = CreditMeter("bloom_seller", base=каталог)
    except Exception:  # noqa: BLE001
        _МЕТР = None       # учёт не должен мешать продавать
    return _МЕТР


def rpc_call(method: str, params: list, *, timeout: int = 20) -> dict:
    """Один вызов узла: Helius, при отказе -- публичный. Ключ не печатается."""
    key = (os.environ.get("HELIUS_API_KEY") or os.environ.get("HELIUS_API") or "").strip()
    адреса = ([f"{HELIUS_RPC}/?api-key={key}"] if key else []) + [PUBLIC_RPC]
    последняя = "адресов узла нет"
    for url in адреса:
        try:
            r = requests.post(url, json={"jsonrpc": "2.0", "id": 1,
                                          "method": method, "params": params},
                               timeout=timeout)
        except requests.RequestException as exc:
            последняя = scrub_all(f"{type(exc).__name__}: {exc}")
            continue
        if url != PUBLIC_RPC:
            м = метр_кредитов()
            if м is not None:
                global _УЧЁТ_ПИШЕТСЯ, _УЧЁТ_ПОЧЕМУ  # noqa: PLW0603
                try:
                    from solana_rpc_client import (  # noqa: PLC0415
                        CREDITS_BY_METHOD, CREDITS_DEFAULT)
                    м.add(CREDITS_BY_METHOD.get(method, CREDITS_DEFAULT),
                          bytes_in=len(r.content or b""))
                    _УЧЁТ_ПИШЕТСЯ, _УЧЁТ_ПОЧЕМУ = True, ""
                except Exception as exc:  # noqa: BLE001
                    # Продавать учёт не мешает, но молчать он не должен:
                    # так уже потерялся весь расход детектора.
                    _УЧЁТ_ПИШЕТСЯ = False
                    _УЧЁТ_ПОЧЕМУ = f"{type(exc).__name__}: {str(exc)[:160]}"
        if r.status_code != 200:
            последняя = scrub_all(f"HTTP {r.status_code}: {r.text[:200]}")
            continue
        try:
            body = r.json()
        except ValueError:
            последняя = "ответ узла не json"
            continue
        if "error" in body:
            последняя = scrub_all(f"RPC error: {str(body['error'])[:200]}")
            continue
        return {"ok": True, "result": body.get("result")}
    return {"ok": False, "why_not": последняя}


def _счета_из_ответа(r: dict, mint: str) -> tuple:
    """Сумма, ui и число счетов из ответа getTokenAccountsByOwner."""
    сумма, ui, счетов = 0, 0.0, 0
    for it in ((r.get("result") or {}).get("value") or []):
        info = ((((it.get("account") or {}).get("data") or {}).get("parsed") or {})
                .get("info") or {})
        if info.get("mint") and info.get("mint") != mint:
            continue          # запасной путь берёт счета программы целиком
        amt = info.get("tokenAmount") or {}
        try:
            сумма += int(amt.get("amount") or 0)
        except (TypeError, ValueError):
            pass
        ui += float(amt.get("uiAmount") or 0.0)
        счетов += 1
    return сумма, ui, счетов


def token_balance_raw(wallet: str, mint: str) -> dict:
    """Остаток токена НА ЦЕПИ.

    Фильтр у getTokenAccountsByOwner -- РОВНО ОДИН: либо mint, либо
    programId. Оба вместе узел отвергает как неверные параметры, и это уже
    стоило живого стенда: сторож 23.09 не сделал ни одной попытки продажи
    при открытой позиции, потому что каждый круг получал отказ, а ветка
    "остаток не прочитан" была единственной, которая при этом молчала.

    Фильтра по минту достаточно и для Token-2022: минт принадлежит одной
    программе токена, и счета этого минта заводятся в ней же. Запасной
    путь (фильтр по программе с отбором по минту у нас) оставлен на случай,
    если узел по минту не ответит -- но он дороже и берёт лишние данные.
    """
    # COMMITMENT -- ТОЛЬКО processed, И ЭТО ПРО ДЕНЬГИ (слово владельца 28.09
    # ночью, п.3а: "остаток читать на processed ... никогда не на finalized").
    # Без него узел отвечал по finalized, а токен-счёт создан в самой покупке
    # секунды назад: при удержании 3.16 с (группа sniper_src) ответ приходил
    # ПУСТОЙ, остаток читался нулём, и позиция закрывалась веткой "продавать
    # нечего" при живом остатке. 28.09 так потеряно 0.794226 SOL на пяти
    # сделках подряд: токены лежали на кошельке, а продажи по таймеру не было.
    r = rpc_call("getTokenAccountsByOwner", [wallet, {"mint": mint},
                                              {"encoding": "jsonParsed",
                                                "commitment": ОСТАТОК_COMMITMENT}])
    if r.get("ok"):
        сумма, ui, счетов = _счета_из_ответа(r, mint)
        return {"ok": True, "raw": сумма, "ui": ui, "accounts": счетов,
                 "filter": "mint", "failures": []}

    сбои = [{"filter": "mint", "why_not": r.get("why_not")}]
    сумма, ui, счетов = 0, 0.0, 0
    удалось = False
    for prog in (TOKEN_CLASSIC, TOKEN_2022):
        r2 = rpc_call("getTokenAccountsByOwner", [wallet, {"programId": prog},
                                                   {"encoding": "jsonParsed",
                                                     "commitment": ОСТАТОК_COMMITMENT}])
        if not r2.get("ok"):
            сбои.append({"filter": f"programId:{prog}", "why_not": r2.get("why_not")})
            continue
        удалось = True
        с, u, к = _счета_из_ответа(r2, mint)
        сумма += с
        ui += u
        счетов += к
    if not удалось:
        return {"ok": False, "failures": сбои,
                 "why_not": "остаток не прочитан ни по минту, ни по программам токена"}
    return {"ok": True, "raw": сумма, "ui": ui, "accounts": счетов,
             "filter": "programId", "failures": сбои}


def kill_sell_active(state=None) -> tuple[bool, str]:
    """Отдельный рубильник ПРОДАЖ. Fail-closed, как и основной.

    Путей ДВА. Первый -- /etc/bloom-executor/KILL_SELL, его ставит владелец
    или деплой. Второй -- файл в каталоге состояния, который служба может
    создать сама: именно через него работает команда /kill_sell из Telegram,
    потому что каталог /etc принадлежит root, а служба работает от bot и
    писать туда не может. Любой из двух файлов -- запрет.
    """
    пути = [kill_sell_file()]
    if state is not None and getattr(state, "kill_sell_path", None):
        пути.append(state.kill_sell_path)
    try:
        for p in пути:
            if p.exists():
                try:
                    почему = p.read_text(encoding="utf-8").strip()[:200]
                except OSError:
                    почему = "(файл не читается -- всё равно запрет)"
                return True, f"рубильник продаж включён: {почему or 'без пояснения'}"
        return False, ""
    except Exception as exc:  # noqa: BLE001
        return True, (f"проверка рубильника продаж не удалась ({type(exc).__name__}) -- "
                       "продажи запрещены: неясность трактуется как запрет")


def telegram(text: str) -> dict:
    """Доклад владельцу. Не настроен -- только в журнал, без падения."""
    token = os.environ.get("TELEGRAM_BOT_TOKEN", "").strip()
    chat = os.environ.get("TELEGRAM_CHAT_ID", "").strip()
    if not token or not chat:
        return {"ok": False, "why_not": "телеграм не настроен -- только журнал"}
    try:
        r = requests.post(f"https://api.telegram.org/bot{token}/sendMessage",
                           json={"chat_id": chat, "text": text[:3500],
                                 "disable_web_page_preview": True}, timeout=15)
        return {"ok": r.status_code == 200, "code": r.status_code}
    except requests.RequestException as exc:
        return {"ok": False, "why_not": scrub_all(f"{type(exc).__name__}: {exc}")}


def due_for_watch(pos: dict, *, grace_s: float, now: float | None = None) -> bool:
    """Пора ли сторожу смотреть на эту позицию.

    Срок считается от ПРИНЯТИЯ запроса Bloom -- так работает таймер
    авто-ордера, и так же должен считать сторож. Если принятия не было
    (упали до ответа), берётся время намерения: позиция всё равно могла
    быть куплена.
    """
    now = now if now is not None else time.time()
    if pos.get("state") == STATE_CLOSED:
        return False
    основа = pos.get("ts_accepted") or pos.get("ts_intent")
    if not основа:
        return True          # непонятно когда -- значит смотреть сейчас
    срок = float(pos.get("sell_after_s") or 0.0)
    return now >= (float(основа) + срок + grace_s)


def слот_покупки(pos: dict):
    """Слот, в котором СЕЛА наша покупка. None -- неизвестен.

    Именно от него отсчитывается удержание: hold_slots -- это слоты сети, а не
    секунды. Поля два, потому что дозаполняются они разными путями (догон
    детектора и выгрузка по цепи), и оба означают одно и то же.
    """
    for ключ in ("lane_landed_slot", "block_slot"):
        зн = (pos or {}).get(ключ)
        if isinstance(зн, int) and зн > 0:
            return зн
    return None


def срок_полосы_по_слотам(pos: dict, *, каталог=None, слот_сети=None) -> dict:
    """Пора ли продавать ПО СЧЁТЧИКУ СЛОТОВ СЕТИ -- БОЛЬШЕ НЕ РЕШАЕТ.

    ОТКАЧЕНО по слову владельца в ночь 29->30.09: решение о сроке вернулось к
    дневному счёту (срок_полосы: слоты x измеренная длина слота). Функция
    оставлена только как измерение -- посмотреть, что счётчик слотов СКАЗАЛ БЫ.
    Возвращать её в решение без слова владельца нельзя: из-за неё продажи ушли
    на 364, 372 и 212 слотов при плане 108.

    ЗАЧЕМ. Удержание задано в слотах, а решение до сих пор принималось в
    секундах: слоты переводились во время через ЗАМЕР длины слота. Замер --
    среднее, а слоты идут неровно, и на удержании 12 слотов ошибка среднего
    сдвигает продажу на несколько слотов. 29.09 по факту: заданные 12 слотов
    давали удержание 25 слотов, заданные 108 -- 107 и 111. Счётчик слотов
    сети врать не может: он и есть та величина, в которой задано удержание.

    ОТКУДА СЛОТ. Из признака жизни детектора (net_slot) с проверкой свежести --
    без сетевого вызова на пути денег.

    НЕ ЗНАЕМ -- НЕ ЗАПРЕЩАЕМ. Если слот сети или слот покупки неизвестны, эта
    функция говорит "не знаю" (пора=None), и решение остаётся за прежним
    счётом по времени. Здесь незнание НЕЛЬЗЯ обращать в запрет: не продать
    вовремя хуже, чем продать на слот раньше или позже.
    """
    из_ = {"пора": None, "почему": None, "слот_сети": None, "возраст_слота_с": None,
            "слот_покупки": None, "нужно_слотов": None, "прошло_слотов": None}
    слотов = (pos or {}).get("hold_slots")
    if not isinstance(слотов, (int, float)) or float(слотов) <= 0:
        из_["почему"] = "удержание в слотах не задано"
        return из_
    из_["нужно_слотов"] = float(слотов)
    с_п = слот_покупки(pos)
    из_["слот_покупки"] = с_п
    if not с_п:
        из_["почему"] = "слот нашей покупки неизвестен"
        return из_
    if слот_сети is None:
        с = слот_сети_из_признака(каталог)
        слот_сети, из_["возраст_слота_с"] = с.get("slot"), с.get("age_s")
        if not слот_сети:
            из_["почему"] = f"слот сети не прочитан: {с.get('why_not')}"
            return из_
    из_["слот_сети"] = слот_сети
    прошло = int(слот_сети) - int(с_п)
    из_["прошло_слотов"] = прошло
    из_["пора"] = прошло >= float(слотов)
    из_["почему"] = (f"прошло {прошло} слотов из {слотов}")
    return из_


def удержание_s(pos: dict, *, длина_слота: float | None = None) -> float:
    """Удержание в СЕКУНДАХ: слоты x ИЗМЕРЕННАЯ длина слота. Дневной расчёт.

    ОДНА ФОРМУЛА НА РЕПОЗИТОРИЙ. Её берут и срок_полосы, и срок_продажи_ts:
    когда их было две, решение и сон расходились.

    Удержание задано в слотах, поэтому длина слота берётся СВЕЖАЯ у замера, а не
    та, что стояла в момент покупки: за время удержания замер мог обновиться, и
    правда в слотах, а не в записанной секунде. Замера нет вовсе -- берём
    sell_after_s из записи, посчитанный длиной на момент покупки.

    длина_слота -- шов для самопроверки: подставить своё число, чтобы решение не
    зависело от файла замера на машине.
    """
    слотов = (pos or {}).get("hold_slots")
    if isinstance(слотов, (int, float)) and float(слотов) > 0:
        дл = длина_слота
        if дл is None and OSW is not None:
            try:
                дл = OSW.длина_слота_s()
            except Exception:  # noqa: BLE001
                дл = None
        if isinstance(дл, (int, float)) and float(дл) > 0:
            return round(float(слотов) * float(дл), 3)
    return float((pos or {}).get("sell_after_s") or 0.0)


def срок_полосы(pos: dict, *, now: float | None = None, каталог=None,
                 слот_сети=None, длина_слота: float | None = None) -> bool:
    """Пора ли продавать позицию ПОЛОСЫ своей отправки.

    РЕШАЕТ ВРЕМЯ: слоты x измеренная длина слота (дневной расчёт). ОТКАТ по
    слову владельца в ночь 29->30.09: "с вечернего деплоя все продажи поздние:
    364, 372, 212 слотов при плане 108 (до деплоя 101-111). Причина -- новый
    расчёт срока по слоту сети. ОТКАТИТЬ расчёт срока на дневной, не чинить
    новый".

    ЧЕМ БЫЛ ПЛОХ СЧЁТ ПО СЛОТУ СЕТИ. Слот брался из признака жизни детектора
    (detector_status.json, поле net_slot), а свежесть этого числа проверялась по
    полю net_slot_age_s ИЗ ТОГО ЖЕ ФАЙЛА. Возраст считается в момент ЗАПИСИ, и
    потому всегда мал -- порог 5 с он проходил всегда. Сам файл пишется раз в
    ПУЛЬС_S = 60 с, то есть сторож сравнивал удержание с номером слота
    давностью до минуты и ждал лишнюю минуту. Живой след: сделка 20:06:02Z
    держалась 364 слота при плане 108, и все 33 круга сторожа писали "ждём срок
    продажи полосы", то есть попытки продажи не было вовсе.

    Время считается от НАШЕЙ отправки и БЕЗ запаса: авто-ордера Bloom у полосы
    нет вовсе, значит после срока ждать нечего.

    каталог и слот_сети ПРИНИМАЮТСЯ И НЕ ИСПОЛЬЗУЮТСЯ: подписи зовущих не
    меняем, но счётчик слотов сети в решении больше не участвует. Не возвращать
    его сюда без слова владельца.
    """
    now = now if now is not None else time.time()
    if pos.get("state") == STATE_CLOSED:
        return False
    основа = pos.get("ts_sent") or pos.get("ts_accepted") or pos.get("ts_intent")
    if not основа:
        return True          # непонятно когда -- значит смотреть сейчас
    return now >= (float(основа) + удержание_s(pos, длина_слота=длина_слота))


# КАК ЧАСТО СЧИТАТЬ МЕТРИКИ ПРОДАВЦА. Круг сторожа теперь 3 с, а метрики
# считаются по ВСЕМ позициям суток: делать это каждый круг незачем.
МЕТРИКИ_КАЖДЫЕ_S = env_float("BLOOM_SELLER_METRICS_S", 60.0)


def _кванти(значения: list, доля: float):
    """Квантиль по списку. Пусто -- None, а не ноль: ноль здесь был бы ложью."""
    if not значения:
        return None
    з = sorted(значения)
    if len(з) == 1:
        return з[0]
    место = доля * (len(з) - 1)
    низ = int(место)
    верх = min(низ + 1, len(з) - 1)
    вес = место - низ
    return з[низ] * (1 - вес) + з[верх] * вес


def срок_продажи_ts(pos: dict):
    """Момент, когда продажа стала ПОРА. None -- не из чего считать.

    У позиции полосы срок идёт от НАШЕЙ отправки и без запаса (см. срок_полосы),
    у позиции площадки -- от ответа площадки плюс запас. Одна формула на оба
    случая соврала бы на величину запаса.
    """
    # УДЕРЖАНИЕ -- ОДНОЙ ФОРМУЛОЙ С РЕШЕНИЕМ (удержание_s): слоты x измеренная
    # длина слота, иначе sell_after_s из записи. Когда формул было две, сон до
    # срока и решение о сроке расходились.
    if pos.get("sell_after_s") is None and not pos.get("hold_slots"):
        return None
    срок = удержание_s(pos)
    if pos.get("lane") == МЕТКА_ПОЛОСЫ:
        основа = pos.get("ts_sent") or pos.get("ts_accepted") or pos.get("ts_intent")
        запас = 0.0
    else:
        основа = pos.get("ts_accepted") or pos.get("ts_intent")
        запас = float(env_float("BLOOM_SELL_GRACE_S", 15.0))
    if not основа:
        return None
    return float(основа) + float(срок) + запас


def ближайший_срок_продажи(позиции: dict) -> float | None:
    """Самый ранний БУДУЩИЙ момент «пора продавать» среди открытых позиций.

    ЗАЧЕМ. Решение владельца 28.09: срок продажи -- точное ожидание до дедлайна,
    а не опрос каждые 3 с. По замеру суток 28.09 зернистость круга давала до 3 с
    задержки на каждой продаже, и это была половина всей задержки сторожа.
    Прошедшие сроки здесь НЕ возвращаются: их обрабатывает сам круг, а спать до
    прошлого нельзя.
    """
    сроки = []
    сейчас = time.time()
    for поз in (позиции or {}).values():
        if not isinstance(поз, dict):
            continue
        if поз.get("state") in (STATE_CLOSED, "closed"):
            continue
        т = срок_продажи_ts(поз)
        if isinstance(т, (int, float)) and float(т) > сейчас:
            сроки.append(float(т))
    return min(сроки) if сроки else None


# СЛОТ СЕТИ БЕЗ СЕТИ. Детектор подписан на слоты и держит счётчик в памяти;
# продавцу слот нужен и для срока удержания, и для метки момента отправки, а
# спрашивать его у узла в пути денег значило бы добавить сетевой вызов.
#
# ПОЧЕМУ ОТДЕЛЬНЫЙ ФАЙЛ, А НЕ ПРИЗНАК ЖИЗНИ (найдено 29.09 живой сделкой).
# Признак жизни детектор пишет раз в ПУЛЬС (по умолчанию 60 с), и его net_slot --
# лестница со ступенью до 60 с, то есть до ~220 слотов. Поле net_slot_age_s при
# этом считается В МОМЕНТ ЗАПИСИ и всегда выглядит свежим: файл минутной
# давности говорит "возраст 0.06 с". Сделка 19:05:05Z с удержанием 108 слотов
# из-за этого держалась 200 слотов (53.7 с вместо 29.2): продавец ждал, пока
# ступень счётчика перепрыгнет порог. Ошибка всегда в одну сторону -- ПОЗЖЕ, --
# но до целой минуты.
#
# Поэтому детектор пишет счётчик слотов в СВОЙ МАЛЕНЬКИЙ ФАЙЛ прямо на пути
# уведомления о слоте (несколько раз в секунду, без сети), а возраст здесь
# считается по ВРЕМЕНИ ВНУТРИ ФАЙЛА и по mtime самого файла -- по тому из них,
# что даёт БОЛЬШИЙ возраст. Признак жизни остаётся запасным путём, и его
# возраст тоже считается с поправкой на mtime.
ФАЙЛ_ПРИЗНАКА_ДЕТЕКТОРА = "detector_status.json"
ФАЙЛ_СЛОТА_СЕТИ = "net_slot.json"
СЛОТ_СЕТИ_СВЕЖЕСТЬ_S = 5.0


def _возраст_файла_s(путь: Path) -> float | None:
    """Сколько секунд назад файл записан. Не прочитать -- None, а не ноль."""
    try:
        return max(0.0, time.time() - путь.stat().st_mtime)
    except Exception:  # noqa: BLE001
        return None


def слот_сети_из_файла(каталог=None, *, свежесть_s: float = СЛОТ_СЕТИ_СВЕЖЕСТЬ_S
                        ) -> dict:
    """net_slot из отдельного файла часов слотов (пишется на пути уведомления).

    Возраст -- НАИБОЛЬШИЙ из двух: по времени внутри файла и по его mtime. Один
    без другого лжёт: время внутри не знает, что файл лежит с прошлой минуты, а
    mtime не знает, что число внутри уже было старым при записи.
    """
    из_ = {"slot": None, "age_s": None, "why_not": None, "откуда": "net_slot.json"}
    try:
        if каталог is None:
            from bloom_exec_state import state_dir  # noqa: PLC0415

            каталог = state_dir()
        путь = Path(каталог) / ФАЙЛ_СЛОТА_СЕТИ
        з = json.loads(путь.read_text(encoding="utf-8"))
    except Exception as exc:  # noqa: BLE001
        из_["why_not"] = f"{type(exc).__name__}: {str(exc)[:80]}"
        return из_
    слот = з.get("net_slot")
    if not isinstance(слот, int) or слот <= 0:
        из_["why_not"] = "в файле часов слотов нет net_slot"
        return из_
    возрасты = []
    т = з.get("ts")
    if isinstance(т, (int, float)) and float(т) > 0:
        возрасты.append(max(0.0, time.time() - float(т)))
    в_ф = _возраст_файла_s(путь)
    if в_ф is not None:
        возрасты.append(в_ф)
    if not возрасты:
        из_["why_not"] = "возраст числа не установить -- ни ts, ни mtime"
        return из_
    возраст = max(возрасты)
    из_["age_s"] = round(возраст, 3)
    if возраст > float(свежесть_s):
        из_["why_not"] = (f"часы слотов старше {свежесть_s} с "
                           f"({round(возраст, 2)} с)")
        return из_
    из_["slot"] = int(слот)
    return из_


def слот_сети_из_признака(каталог=None, *, свежесть_s: float = СЛОТ_СЕТИ_СВЕЖЕСТЬ_S
                           ) -> dict:
    """Слот сети: сначала часы слотов, потом признак жизни. Старое -- не число.

    Имя оставлено прежним: его зовут и срок удержания, и метка отправки, и
    самопроверки. Изменился только источник -- сперва быстрый файл часов.
    """
    быстро = слот_сети_из_файла(каталог, свежесть_s=свежесть_s)
    if быстро.get("slot"):
        return быстро
    из_ = {"slot": None, "age_s": None, "why_not": None,
            "откуда": ФАЙЛ_ПРИЗНАКА_ДЕТЕКТОРА,
            "часы_why_not": быстро.get("why_not")}
    try:
        if каталог is None:
            from bloom_exec_state import state_dir  # noqa: PLC0415

            каталог = state_dir()
        путь = Path(каталог) / ФАЙЛ_ПРИЗНАКА_ДЕТЕКТОРА
        з = json.loads(путь.read_text(encoding="utf-8"))
    except Exception as exc:  # noqa: BLE001
        из_["why_not"] = f"{type(exc).__name__}: {str(exc)[:80]}"
        return из_
    слот = з.get("net_slot")
    возраст = з.get("net_slot_age_s")
    if not isinstance(слот, int) or слот <= 0:
        из_["why_not"] = "в признаке детектора нет net_slot"
        return из_
    # ВОЗРАСТ ЧИСЛА = возраст внутри файла ПЛЮС возраст самого файла. Признак
    # жизни пишется раз в минуту, и без поправки на mtime минутная ступень
    # счётчика выглядела свежей -- ровно из-за этого сделка 19:05:05Z держалась
    # 200 слотов вместо 108.
    полный = float(возраст) if isinstance(возраст, (int, float)) else None
    в_ф = _возраст_файла_s(путь)
    if в_ф is not None:
        полный = (в_ф if полный is None else полный + в_ф)
    if полный is None:
        из_["why_not"] = "возраст net_slot не установить -- ни поля, ни mtime"
        return из_
    из_["age_s"] = round(полный, 3)
    if полный > float(свежесть_s):
        из_["why_not"] = (f"net_slot старше {свежесть_s} с "
                           f"({round(полный, 2)} с c поправкой на mtime файла) -- "
                           "за слот отправки не годится")
        return из_
    из_["slot"] = int(слот)
    return из_


